using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBevelGpuLifecycleValidation {
 public static void Run(){try{Validate();UnityEditor.EditorApplication.Exit(0);}catch(Exception e){UnityEngine.Debug.LogException(e);UnityEditor.EditorApplication.Exit(1);}}

 public static void Validate(){int checks=0;void Check(bool valid,string message){if(!valid)throw new Exception(message);checks++;}var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);var first=new GameObject("GPU lifecycle first");var second=new GameObject("GPU lifecycle shared instance");var a=first.AddComponent<MeshFilter>();var b=second.AddComponent<MeshFilter>();a.sharedMesh=b.sharedMesh=mesh;doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});var source=mesh.vertices;try{using(var preview=new StudioMeshToolPreview(doc,new[]{0})){var target=preview.Targets[0];var face=target.Topology.Faces[0];var edge=new[]{(face.Vertices[0],face.Vertices[1])};Mesh previous=null;foreach(var setting in new[]{(.1f,0),(.4f,0),(.5f,2),(.6f,2),(.3f,0)}){var result=target.Topology.BevelEdges(target.Work,edge,new StudioMeshCuts.BevelOptions{Width=setting.Item1,Subdivisions=setting.Item2,Tension=1});target.VertexUpdate=result.VertexUpdate;target.VertexUpdateStart=result.VertexUpdateStart;target.PublishedPositions=result.PublishedPositions;target.IsBevelPreview=true;preview.Publish(true);target.UseGpuPreview(a);target.UseGpuPreview(b);Check(a.sharedMesh==b.sharedMesh&&a.sharedMesh!=mesh,"Shared instances must use one GPU mirror");if(setting.Item1==.4f||setting.Item1==.6f)Check(a.sharedMesh==previous,"Width must preserve GPU mesh identity");else if(previous)Check(a.sharedMesh!=previous,"Topology change must replace GPU mesh");previous=a.sharedMesh;}
 preview.Commit("GPU bevel lifecycle");Check(a.sharedMesh==mesh&&b.sharedMesh==mesh,"Commit restores authoritative renderer meshes");Check(!mesh.vertices.SequenceEqual(source),"Commit retains generated CPU geometry");}
 var committed=mesh.vertices;StudioUndo.PerformUndo();Check(mesh.vertices.SequenceEqual(source),"Undo restores pre-bevel geometry");Check(a.sharedMesh==mesh&&b.sharedMesh==mesh,"Undo retains authoritative renderer binding");StudioUndo.PerformRedo();Check(mesh.vertices.SequenceEqual(committed),"Redo restores committed bevel");
 using(var preview=new StudioMeshToolPreview(doc,new[]{0})){var target=preview.Targets[0];var face=target.Topology.Faces[0];var result=target.Topology.BevelEdges(target.Work,new[]{(face.Vertices[0],face.Vertices[1])},new StudioMeshCuts.BevelOptions{Width=.1f,Subdivisions=0,Tension=1});target.VertexUpdate=result.VertexUpdate;target.VertexUpdateStart=result.VertexUpdateStart;target.PublishedPositions=result.PublishedPositions;target.IsBevelPreview=true;preview.Publish(true);target.UseGpuPreview(a);Check(a.sharedMesh!=mesh,"Second preview attaches GPU mirror");preview.Restore();Check(a.sharedMesh==mesh,"Cancel restores authoritative renderer");Check(mesh.vertices.SequenceEqual(committed),"Cancel preserves committed geometry");}
 Check(!Resources.FindObjectsOfTypeAll<Mesh>().Any(m=>m.name=="Studio live bevel GPU preview"),"GPU mirror meshes released");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-gpu-lifecycle-result.txt")),"PASS "+checks+" GPU identity, topology, shared-instance, commit, Undo/Redo, cancel and disposal assertions");}finally{StudioUndo.ClearUndo(mesh);StudioUndo.ClearUndo(doc);Object.DestroyImmediate(first);Object.DestroyImmediate(second);Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);}}
}
